sub install {
    my ($tarball, $dest) = @_;
    my $tar = Archive::Tar->new($tarball) or die Archive::Tar->error;
    my $count = 0;
    for my $file ($tar->get_files) {
        next unless $file->is_file;
        my $target = "$dest/" . $file->full_path;
        make_path(dirname($target));
        open(my $out, '>', $target) or die "cannot write $target: $!";
        binmode $out;
        print {$out} $file->get_content;
        close $out;
        $count++;
    }
    return $count;

